const prompt = require('prompt-sync')();

function reverse(){
    let num = prompt(`Enter a number to be reversed: `);
    let ans = ``;
    for(i = num.length; i > 0; i--){
        if(num[i-1] === `-`)
            ans = '-' + ans;
        else
            ans += num[i-1];
    }
    return ans;
}
console.log(reverse());